SELECT
    warning_order_id AS warningOrderId,
    warning_type_id AS warningTypeId,
    extra_field AS extraField,
    CAST(sub_scenes AS CHAR) AS subScenes
FROM ${tableName}
WHERE delete_flag = '0'

    AND warning_order_id > #{lastId}

ORDER BY warning_order_id ASC
LIMIT #{batchSize}

